  "Unlock all 50+ AI tools and unlimited documents.": "\u0627\u0641\u062A\u062D \u062D\u062F\u0648\u062F\u0627\u064B \u0623\u0639\u0644\u0649 \u0648\u0645\u064A\u0632\u0627\u062A \u0627\u062D\u062A\u0631\u0627\u0641\u064A\u0629 \u0625\u0636\u0627\u0641\u064A\u0629.",
  "User": "\u0645\u0633\u062A\u062E\u062F\u0645",
  "Soon": "\u0642\u0631\u064A\u0628\u0627\u064B",
  "Beta": "\u062A\u062C\u0631\u064A\u0628\u064A",
  "Delete My Account": "\u062D\u0630\u0641 \u062D\u0633\u0627\u0628\u064A",
