  "Your profile and account credentials": "\u0645\u0644\u0641\u0643 \u0627\u0644\u0634\u062E\u0635\u064A \u0648\u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0639\u062A\u0645\u0627\u062F \u0627\u0644\u062D\u0633\u0627\u0628",
  "All projects (CVs, cover letters, documents)": "\u0643\u0644 \u0627\u0644\u0645\u0634\u0627\u0631\u064A\u0639 (\u0627\u0644\u0633\u064A\u0631 \u0627\u0644\u0630\u0627\u062A\u064A\u0629 \u0648\u062E\u0637\u0627\u0628\u0627\u062A \u0627\u0644\u062A\u063A\u0637\u064A\u0629 \u0648\u0627\u0644\u0645\u0633\u062A\u0646\u062F\u0627\u062A)",
  "All files and exports": "\u0643\u0644 \u0627\u0644\u0645\u0644\u0641\u0627\u062A \u0648\u0627\u0644\u062A\u0635\u062F\u064A\u0631\u0627\u062A",
  "All AI conversations and usage history": "\u0643\u0644 \u0645\u062D\u0627\u062F\u062B\u0627\u062A \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064A \u0648\u0633\u062C\u0644 \u0627\u0644\u0627\u0633\u062A\u062E\u062F\u0627\u0645",
  "All activity logs and preferences": "\u0643\u0644 \u0633\u062C\u0644\u0627\u062A \u0627\u0644\u0646\u0634\u0627\u0637 \u0648\u0627\u0644\u062A\u0641\u0636\u064A\u0644\u0627\u062A",
  "Type": "\u0627\u0643\u062A\u0628",
  "to confirm": "\u0644\u0644\u062A\u0623\u0643\u064A\u062F",
