  "Production app URL": "\u0631\u0627\u0628\u0637 \u062A\u0637\u0628\u064A\u0642 \u0627\u0644\u0625\u0646\u062A\u0627\u062C",
  "Live service checks before launch. Secrets remain server-side.": "\u0641\u062D\u0648\u0635\u0627\u062A \u0644\u0644\u062E\u062F\u0645\u0627\u062A \u0627\u0644\u062D\u064A\u0629 \u0642\u0628\u0644 \u0627\u0644\u0625\u0637\u0644\u0627\u0642. \u062A\u0628\u0642\u0649 \u0627\u0644\u0623\u0633\u0631\u0627\u0631 \u0639\u0644\u0649 \u0627\u0644\u062E\u0627\u062F\u0645.",
  "ready": "\u062C\u0627\u0647\u0632",
  "Notifications unavailable": "\u0627\u0644\u0625\u0634\u0639\u0627\u0631\u0627\u062A \u063A\u064A\u0631 \u0645\u062A\u0627\u062D\u0629",
  "Email templates unavailable": "\u0642\u0648\u0627\u0644\u0628 \u0627\u0644\u0628\u0631\u064A\u062F \u063A\u064A\u0631 \u0645\u062A\u0627\u062D\u0629",
  "Backups are managed by the database hosting provider. No in-app backup API is configured, so this panel will not pretend to create or download backups.": "\u062A\u064F\u062F\u0627\u0631 \u0627\u0644\u0646\u0633\u062E \u0627\u0644\u0627\u062D\u062A\u064A\u0627\u0637\u064A\u0629 \u0628\u0648\u0627\u0633\u0637\u0629 \u0645\u0632\u0648\u062F \u0627\u0633\u062A\u0636\u0627\u0641\u0629 \u0642\u0627\u0639\u062F\u0629 \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A. \u0644\u0627 \u062A\u0648\u062C\u062F \u0648\u0627\u062C\u0647\u0629 \u0646\u0633\u062E \u0627\u062D\u062A\u064A\u0627\u0637\u064A \u0645\u0647\u064A\u0623\u0629 \u062F\u0627\u062E\u0644 \u0627\u0644\u062A\u0637\u0628\u064A\u0642\u060C \u0644\u0630\u0644\u0643 \u0644\u0646 \u062A\u062F\u0651\u0639\u064A \u0647\u0630\u0647 \u0627\u0644\u0644\u0648\u062D\u0629 \u0625\u0646\u0634\u0627\u0621 \u0646\u0633\u062E \u0623\u0648 \u062A\u0646\u0632\u064A\u0644\u0647\u0627.",
  "Use the Supabase project backup controls for real backup and restore operations.": "\u0627\u0633\u062A\u062E\u062F\u0645 \u0623\u062F\u0648\u0627\u062A \u0627\u0644\u0646\u0633\u062E \u0627\u0644\u0627\u062D\u062A\u064A\u0627\u0637\u064A \u0641\u064A \u0645\u0634\u0631\u0648\u0639 Supabase \u0644\u0639\u0645\u0644\u064A\u0627\u062A \u0627\u0644\u0646\u0633\u062E \u0648\u0627\u0644\u0627\u0633\u062A\u0639\u0627\u062F\u0629 \u0627\u0644\u0641\u0639\u0644\u064A\u0629.",
  "API key metadata unavailable": "\u0628\u064A\u0627\u0646\u0627\u062A \u0645\u0641\u0627\u062A\u064A\u062D API \u063A\u064A\u0631 \u0645\u062A\u0627\u062D\u0629",
  "Metadata only \u2014 secrets stay server-side": "\u0628\u064A\u0627\u0646\u0627\u062A \u0648\u0635\u0641\u064A\u0629 \u0641\u0642\u0637 \u2014 \u062A\u0628\u0642\u0649 \u0627\u0644\u0623\u0633\u0631\u0627\u0631 \u0639\u0644\u0649 \u0627\u0644\u062E\u0627\u062F\u0645",
