  "Existing flags only": "\u0627\u0644\u0623\u0639\u0644\u0627\u0645 \u0627\u0644\u0645\u0648\u062C\u0648\u062F\u0629 \u0641\u0642\u0637",
  "Could not load users": "\u062A\u0639\u0630\u0631 \u062A\u062D\u0645\u064A\u0644 \u0627\u0644\u0645\u0633\u062A\u062E\u062F\u0645\u064A\u0646",
