  "Complimentary Business": "Business \u0645\u062C\u0627\u0646\u064A",
  "Expires (optional)": "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0627\u0646\u062A\u0647\u0627\u0621 (\u0627\u062E\u062A\u064A\u0627\u0631\u064A)",
  "Save Complimentary Access": "\u062D\u0641\u0638 \u0627\u0644\u0648\u0635\u0648\u0644 \u0627\u0644\u0645\u062C\u0627\u0646\u064A",
  "This changes product access only. It does not create a Stripe subscription or affect MRR.": "\u0647\u0630\u0627 \u064A\u063A\u064A\u0651\u0631 \u0635\u0644\u0627\u062D\u064A\u0629 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0627\u0644\u0645\u0646\u062A\u062C \u0641\u0642\u0637. \u0644\u0627 \u064A\u0646\u0634\u0626 \u0627\u0634\u062A\u0631\u0627\u0643 Stripe \u0648\u0644\u0627 \u064A\u0624\u062B\u0631 \u0639\u0644\u0649 \u0627\u0644\u0625\u064A\u0631\u0627\u062F \u0627\u0644\u0634\u0647\u0631\u064A \u0627\u0644\u0645\u062A\u0643\u0631\u0631.",
  "Build, preview and publish": "\u0623\u0646\u0634\u0626 \u0648\u0639\u0627\u064A\u0646 \u0648\u0627\u0646\u0634\u0631",
  "More website tools": "\u0627\u0644\u0645\u0632\u064A\u062F \u0645\u0646 \u0623\u062F\u0648\u0627\u062A \u0627\u0644\u0645\u0648\u0642\u0639",
