  "Project & domain": "\u0627\u0644\u0645\u0634\u0631\u0648\u0639 \u0648\u0627\u0644\u0646\u0637\u0627\u0642",
  "Start a new website\u2026": "\u0627\u0628\u062F\u0623 \u0645\u0648\u0642\u0639\u064B\u0627 \u062C\u062F\u064A\u062F\u064B\u0627\u2026",
  "Project actions": "\u0625\u062C\u0631\u0627\u0621\u0627\u062A \u0627\u0644\u0645\u0634\u0631\u0648\u0639",
